INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Иртиботи обори қатрагӣ бо саломатии маш</h2><p>Барои рӯиҳои сабзӣ мисли маш, шароити реша ва замин омили муҳим барои муқовимат ба бемориҳо ва ҳуҷуми зараррасониҳо мебошад. Дар обори қатрагӣ, боиси он ки рутубат бо шакли маҳаллӣ ва назоратшуда таҳвил меёбад, паҳншавии ниҳоии об ва моддаҳои ғизоӣ дар минтақаи реша (root zone) фарқии барҷое нисбат ба обори сатҳӣ дорад. Ин ҳолат метавонад ҳамчунин аз паҳншавии қаразҳои заминзист пӯшиш диҳад ва бо эҷоди беҳтарини якҷоягии замин, ба кам шудани стресси рӯӣ кӯмак расонад. Маш рӯии ҳассос ба рутубати иловагӣ аст ва обори назоратшуда дақиқтарин усул барои нигоҳ доштани мувозинати рутубат дар атрофи реша мебошад.</p><p>Дар баъд, бо таҳлили паҳншавии умумии зараррасониҳо ва бемориҳои маш, меомӯзем, ки системаи навъии туп ва қатрагӣ чӣ таъсире дорад бар пешгирии назорати ин мушкилиҳо. Инчунин роҳҳои амали помпагӣ, танзими шадидӣ ва ҳангоми пашшони муҳаллиқ низ шарҳ дода мешаванд, то ки кишидор бо камтарин хатар, маҳсули сифатноктар ва саломаттар дошта бошад.</p><h2>Таъсири обори қатрагӣ ба паҳншавии зараррасониҳо ва бемориҳо</h2><p>Обори қатрагӣ бо тағйир додани шароити рутубатиҳои муҳити реша, рафтори бисёр зараррасониҳо ва бемориҳоро тағйир медиҳад. Яке аз муҳимтарин самтҳои он кам шудани сатҳи рутубат дар сатҳи замин аст. Дар обори сатҳӣ, рутубати баланд дар қабатҳои болоӣ метавонад ҳамчун мизбони мувофиқ барои ҳашарот ва тухмгузории қатъкунанда сар карда шавад. Аммо дар обори маҳаллӣ, рутубат мустақиман ба реша мерасад ва сатҳи замин дар масофаҳои дароз хушкتر боқӣ мемонад. Ин масъала метавонад паҳншавии баъзе ҳашароти заминзист ва зинги решаи кам шаданро кам кунад.</p><p>Аз ҷиҳати дигар, оварини бо тамғазаки чорчашеӣ метавонад, агар дуруст идора нашуда шавад, бо зиёдшавии намноки решаҳо ба рушди зичҳои заминӣ кӯмак расонад. Бинобар ин, танзими дақиқи суръати чорчашоӣ, тайини вақти пашпӯшӣ ва интихоби ришаи тамғазакӣ-и мувофиқ муҳим аст. Агар решаҳои чӯл (маш) мунтазам хобанд, хавфи сар задани бемории пӯсаки решаҳо ва бемориҳои бактериявӣ зиёд мешавад. Барои пешгирии ин мушкилот бояд аз шидатҳои мувофиқ истифода бурд ва ба ҷои нигоҳ доштани мунтазами хоб, ба чархаки хушкӣ ва намӣ овардан ба реша диққат кард.</p><h3>Бемориҳои маъмули маш дар шароити оварини бо тамғазаки чорчашеӣ</h3><p>Дар парвариши маш бемориҳои маъмулӣ, ба монанди занг задани решаҳо, зичи заминӣ ва бактерияи моҳ (сахтшавии решаҳо), зери таъсири мустақими оварин мебошанд. Занг задани решаҳо дар шароите, ки намноки замин баланд ва ҳарорат миёна аст, тезтар рушд мекунад. Бо оварини бо тамғазаки чорчашеӣ, агар шидат дуруст танзим шавад, метавон аз ҷамъшавии намнокии дар лавҳаҳои чуқуртар пешгирӣ кард. Ҳамчунин, бемориҳои бактериявӣ дар шароите, ки намнокии решаҳо зиёд аст, бештар рушд мекунанд. Бинобар ин, яке аз принципҳои асосии идоракунии ин зараррасонҳо дар оварини бо тамғазаки чорчашеӣ, идоракунии дақиқи ҳаҷм ва вақти оварин аст.</p><h3>Зараррасонҳои сабзавотҳо ва рафторашон дар оварини бо тамғазаки чорчашеӣ</h3><p>Ҳашарот ба монанди кирми заргард, мугъсаки заминӣ ва пашшаки заминӣ метавонанд дар шароити намнокии муайян фаъолияти бештар дошта бошанд. Кирми заргард аз намнокии замин барои боррасӣ истифода мебарарад. Кам шудани сатҳи намнокии дар лавҳаҳои болоии замин, паноҳгоҳи беҳтар барои боррасӣ эҷод мекунад. Бинобар ин, идоракунии сатҳи намноки бо системаи ришаи тамғазакӣ метавонад ба кам шудани фаъолияти зараррасони сатҳӣ кӯмак расонад. Бақсат, зараррасонҳое, ки мустақиман аз реша ғизо мегиранд, метавонанд аз намнокии баланди реша фоида бароянд. Бинобар ин, мувозинат байни оварини кофӣ ва пешгирии хоб кардан, асоси муҳимтарин аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ماش-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های ماش با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation маш</figcaption></figure><h2>Нуқтаҳои амалӣ барои кам кардани хавфи зараррасонҳо ва бемориҳо</h2><p>Барои идоракунии самараноки зарароварон ва бемориҳои маш дар системаи оғоздихӣ бо муҳраҳо, риоя кардани нуқтаҳои зерин зарур аст:</p><ul><li>Танзими суръати муҳраҳо вобаста ба шароити обӣ ва ҳарорат: Дар рӯзҳои гарм, кам кардани суръати муҳраҳо ва зиёд кардани шумораи абрфаштҳои кӯтоҳмуддат ба нигоҳдории намии кофӣ бе таглидҳо (ғарқобӣ) кӯмак мекунад.</li><li>Истифодаи оби мувофиқ ва бе ифлос: Агар оби истифодашуда омос, моддаҳои кимиёвӣ ё бактерияҳои зараровар дошта бошад, метавонад бемориҳои решаҳоро шидат бахшад. Об бояд аз ҷиҳати кимиёвӣ ва микробиологӣ санҷиш шавад.</li><li>Идоракунии шодахт (шодобӣ): Шодахтҳои мувофиқ аз омосзудан ва пӯшидани масираҳои муҳраҳо пешгирӣ мекунанд. Интихоби намуди шодахт вобаста ба сифати об ва намуди хок, муҳим аст.</li><li>Вақтгузории абрфашт: Абрфаштҳои такрорӣ ва дарозмуддат муҳити ҳамешагӣ намнокро меиборанд. Ба ҷои ин усул, абрфаштҳои кӯтоҳтар ва бо фосилаи мунтазам тавсия дода мешавад.</li><li>Тағйири намуни корпак: Аз коришҳои такрорӣ ва якмаҳсулот дар минтақае, ки таърихи зарардидагӣ дорад, худдорӣ кунед. Чархи корпак бо дигар гиёҳон ба кам шудани шумораи зарароварон дар хок кӯмак мекунад.</li></ul><p>Барои маълумоти бештар дар бораи роҳҳои ҷамъбасти кориши хур бо усулҳои мувофиқи оғоздихӣ, шумо метавонед мақолаи Раҳнамои ҷамъбасти кориши хур бо усули оғоздихиро хонданед. Усулҳои мусоид барои идоракунии зарароварон ва бемориҳои сабзавот дар ин мақола шарҳ дода шудаанд.</p><h2>Идоракунии дақиқи нӯри типӣ ва муҳраҳо дар кориши маш</h2><p>Интихоби навъи мувофиқи бача (шланг) ва қатқата (қушорӣ) бар асоси сечкӣ ва шартҳои парвариш яке аз муҳимтарин омили кам кардани хатари зарароварон аст. Навъҳои қатқата бо қатқатаи хурд ва масофагузори баробар имконияти тақсимоти якхелаи тарроҳиро фароҳам меорад. Аммо агар сипарднокӣ (қатқата) беш аз ҳадд оҳиста бошад, реша дар тараллоии баланд ҷойгир мешавад ва агар тез бошад, метавонад об ба қабатҳои сатҳӣ расад ва ба ҷои реша хокро тар мекунад. Бинобар ин, суръати қатқата бояд дақиқан мувофиқи ниёзи шинакро тағйир дода шавад.</p><p>Таркиши системаи қатқатаи қатқата дар сатҳи деҳкорӣ, ба ҷои як нуқта, метавонад ба беҳтар кардани якхелагии реша расидан кӯмак кунад. Ҳамчунин, агар хоки шумо виллӣ (иллӣ) бошад, истифодаи қатқата бо омази баландтар ва масофаи камтар ба пешгирии зарро дар каналҳои қатқата кӯмак мекунад. Барои маълумоти пурра дар бораи навъҳои гуногуни бача ва истифодаи онҳо, мақолаи «Навъҳои бача»-ро хонед. Дар он мақола фарқияти функсионалии бачаҳои баргардонишда, бачаҳои баргардонишда ва бачаҳои баргардонишда дар шароитҳои гуногуни хок шарҳ дода шудааст.</p><h2>Зарароварон ва бемориҳои шинакро бо обкории қатқата (қушорӣ) дар фаслҳои гуногун</h2><p>Таъсири обкории қатқата (қушорӣ) бар паҳншавии зарароварон ва бемориҳои шинакро дар фаслҳои гуногун фарқ мекунад. Дар фаслҳои гарм, ҳарорати баланд ва тарроҳии кам боиси камтар рушд ёфтани решаи шинакро менамояд. Дар ин шартҳо хатари хушкшавии реша вуҷуд дорад. Барои паири, аз қатқатаи кӯтоҳ ва такроршаванда бо дақиқати баланд истифода бурда мешавад. Аммо агар тарроҳии кам назорат нашавад, дигаргунии обии бунёд пайдо мешавад ва реша ҳассосият ба зарароварони хокӣ меафзояд.</p><p>Дар фасли сард, решагӣи маш боздори мешавад ва хатари оббандӣ зиёд мегардад. Суоябии зиёд дар ин фаслҳо ба афзоиши зангӯбӯриҳо ва бактерияҳо дар решаҳо меорузад. Барои ин, дар моҳҳои сард, кам кардани суръати оварӣ бо қатра ва зиёд кардани фосилаҳои хушк кардани решаҳо зарур аст. Инчунин, дар ин фасл, назорати намии решаҳо дар қабатҳои амиқ муҳим аст, то аз пайдо шудани муҳити доими тар обгир овардан пешгирӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ماش-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های ماش با آبیاری قطره‌ای - تصویر 2"/><figcaption>заҷроҳу зериҳои ҳосил, бемориҳои ҳосил, оварӣ бо қатра, маш</figcaption></figure><h2>Саволҳои мубориз (FAQ)</h2><ol><li><p><strong>Оё оварӣ бо қатра ба идоракунии зангӯбӯрии решаҳои маш кӯмак мекунад?</strong></p><p>Бале, агар суръати оварӣ бо қатра дуруст танзим шавад ва муҳлати мувофиқ истифода шуда бошад, метавонад аз назобиши зиёд дар қабатҳои хок пешгирӣ кунад ва афзоиши зангӯбӯрии решаҳоро кам кунад. Аммо, агар решагӣи маш ба сабаби хушкии шадиди решаҳо боздор шавад, ҳассосият ба зангӯбӯр зиёд мегардад.</p></li><li><p><strong>Оё истифодаи муҳлат дар системаи оварии қатраӣ барои маш зарур аст?</strong></p><p>Бале, муҳлатҳои мувофиқ, ахсусан дар оварии қатраӣ бо нӯҳати типӣ, аз ҷамъшавии лой ва пӯшидании роҳҳои қатра овардан пешгирӣ мекунанд. Интихоби намуди муҳлат вобаста ба муҳлати оби ва намуди хок, омили муҳим барои фаъолияти дурусти система аст.</p></li><li><p><strong>Ҳангоме ки бояд аз паҳкунандаи пурра истифода барам?</strong></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ماش-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های ماش با آبیاری قطره‌ای - تصویر 3"/><figcaption>азобҳо ва бемориҳо, орошӣ по-qатра, маш</figcaption></figure><p>Пуркунии такрорӣ (спрей), вақте ки зичии об мувофиқ аст, ҳарорат миёна аст ва сатҳинамуди намдорӣ ба афзоиш ниёз дорад, тавсия дода мешавад. Аммо дар шароити хушк ва ҳарорати баланд, пуркуниҳо тӯлонӣ боиси гилгирӣи решаҳо ва эҷоди муҳити муносиб барои қаричҳо мегардад. Беҳтар аст пуркуниҳои кӯтоҳтар бо фосилаҳои мунтазам истифода шавад.</p></li></ol><h2>Хулоса ва тавсияҳои охирин</h2><p>Коркарди азобҳо ва бемориҳои маш бо ороиши по-qатра тақозо мекунад, ки зичиҳои мувофиқро пайваст кард, суръати по-qатраро дақиқ танзим кунад ва вақти пуркуниро дуруст тартиб диҳад. Бо риояи ин меъёрҳо, метавон корҳати гирифтани бемориҳои қаричӣ ва бактериявиро кам кард ва ҳамзамон аз хушкшавии решаҳо ва фишори растани пешгирӣ намуд. Инчунин, интихоби намуди мувофиқи навар чопӣ бар асоси зичии хок нақши муҳимро дар тақсимоти баробари намдорӣ боз мекунад.</p><p>Бо назардошти муҳим будани коркарди решаот ва зичии намдорӣ дар кам кардани азобҳо, омӯзиши роҳнамои ҷамъи дар бораи зичиҳои об ва ҳаллаши ороиши по-qатра тавсия дода мешавад. Шумо метавонед мақолаи "шароити решаҳо дар оби карола"-ро омӯзед, то дарки беҳтари таваҷҷуҳи решаҳо ва зичии намдорӣ дар минтақаҳое, ки шароитҳои махсус доранд, пайдо кунед.</p><p>Дар охир, ороиши по-qатра васъати қудрати баланд барои коркарди азобҳо ва бемориҳои маш аст, аммо ин васъата бе иҷрои меъёрҳо ва риояи принсибҳои зичӣ наметавонад аз афзоиши азобҳо пешгирӣ кунад. Бинобар ин, тавсияи охирин ин аст, ки системаи ороиши по-qатраватонро бо меъёрҳои зичиҳои мувофиқ, танзуми дақиқ ва коркарди дурусти намдории решаҳо дар фаслҳои гуногун мувофиқат диҳед, то натиҷаи муваффақ дар кам кардани азобҳо ва баланд бардоштани сифати маҳсулот пайдо кунед.</p>\n<p><strong>Мавзӯъҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/green-beans-yield-per-hectare-factors/">green beans yield per hectare factors</a>， <a href="https://navar-abyari.ir/%d9%87%d8%b2%db%8c%d9%86%d9%87-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a8%d8%b1%d8%a7%db%8c-%db%8c%da%a9-%d9%87%da%a9%d8%aa%d8%a7%d8%b1-%da%86%d9%82%d8%af%d8%b1-%d8%a7%d8%b3%d8%aa%d8%9f/">Талафоти напичи тира бар як гектар чӣ қадар аст?</a>، <a href="https://navar-abyari.ir/%d8%a7%d9%86%d9%88%d8%a7%d8%b9-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be/">Навъҳои напичи тира</a>، <a href="https://navar-abyari.ir/%D8%B4%D8%B1%D9%8A%D8%B7-%D8%A7%D9%84%D8%B1%D9%8A-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%D9%8A%D8%B7-%D9%81%D9%8A-%DA%A9%D8%B1%D8%A8%D9%84%D8%A7/">D8B4D8B1D98AD8B7 D8A7D984D8B1D98A D8A8D8A7D984D8AAD986D982D98AD8B7 D981D98A DAA9D8B1D8A8D984D8A7</a></p>','Хатоҳои ва бемориҳои бодир ҷавдорӣ бо пашсакиш: Роҳнамои ҷамъи кунунии хибар','Дар ин мақола мо таҳқиқ мекунем, ки обёри қатрагӣ чӣ гуна идоракунии зарарбахшҳо ва бемориҳои чойро тағйир медиҳад ва бо пешниҳоди маслиҳатҳои амалӣ аз помпушавӣ то танзими шиддат, ба камакундани хатарии зарар пардохт карда истодаем.','publish','closed','closed','khatotoj-vabemorihoy-bodir-javodori-bobashmakish-rohnamoyi-jamii-kununi-hibar',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
